/**
 * generated by stackra gen from src/config/csp.config.ts, src/config/edge.config.ts
 * (lookupRedirects, redirectCacheSeconds, notFoundLog) and src/config/env.config.ts (apiUrl)
 * — do not edit
 * Purpose: the root middleware of the server build, in order. `securityHeaders` mints the request's
 *          CSP nonce before anything renders, then sets the CSP header on every response, and on an
 *          HTML page `Cache-Control: private, no-cache`, no `Vary` and no `Set-Cookie`.
 *          `notFoundRedirects` runs only when the router answers an HTML 404: it asks the
 *          experience `seo` module for a redirect (edge-cached as data, same-site targets only,
 *          failing open) or records the 404 after the response is sent.
 * Boundary: config classes are resolved from the request's container, never read as statics; the
 *           CSP baseline is @stackra/csp's and the config only adds sources. HTML is never cached
 *           by a shared cache (ADR 0297 d3), the URL alone selects the content (d4), and a GET for
 *           a page never sets a cookie, because consent and the locale choice live in the browser
 *           (ADR 0298 d6); the e2e tier asserts all three. Server only: React Router keeps
 *           `middleware` out of the client build.
 * Runtime: worker
 */
import type { MiddlewareFunction, RouterContextProvider } from "react-router";
import { contentSecurityPolicy, cspHeaderName, createNonce, CspConfig } from "@stackra/csp";
import { RecordNotFoundAction, ResolveRedirectQuery } from "#stackra/clients/experience";
import { EdgeConfig } from "#src/config/edge.config";
import {
  clientsContext,
  containerContext,
  envContext,
  executionContext,
  nonceContext,
  reporterContext,
} from "./context";

/** A redirect the experience `seo` module answered, or `null` for none. */
type SeoRedirect = { readonly to: string; readonly status: 301 | 302 } | null;

/** A page request: only these get the HTML cache rule, the redirect lookup and the 404 log. */
function isHtmlNavigation(request: Request): boolean {
  return request.method === "GET" && (request.headers.get("accept") ?? "").includes("text/html");
}

/** The nonce first, then the CSP header and the HTML rules on whatever the router answered. */
export const securityHeaders: MiddlewareFunction<Response> = async ({ request, context }, next) => {
  const nonce = createNonce(); // 128 bits from crypto.getRandomValues, base64
  context.set(nonceContext, nonce);
  const response = await next();
  const csp = context.get(containerContext).get(CspConfig);
  const env = context.get(envContext);
  response.headers.set(
    cspHeaderName(csp),
    contentSecurityPolicy(csp, { connect: [env.apiUrl], nonce }),
  );
  if ((response.headers.get("content-type") ?? "").startsWith("text/html")) {
    response.headers.set("Cache-Control", "private, no-cache");
    response.headers.delete("Vary");
    if (request.method === "GET") response.headers.delete("Set-Cookie");
  }
  return response;
};

/** On an HTML 404 only: the tenant's redirect, else the 404 record after responding. */
export const notFoundRedirects: MiddlewareFunction<Response> = async (
  { request, context },
  next,
) => {
  const response = await next();
  if (response.status !== 404 || !isHtmlNavigation(request)) return response;

  const edge = context.get(containerContext).get(EdgeConfig);
  const url = new URL(request.url);
  const redirect = edge.lookupRedirects ? await lookupRedirect(url, edge, context) : null;
  // a fresh response, not `Response.redirect`: the outer middleware still sets its headers
  if (redirect)
    return new Response(null, { status: redirect.status, headers: { Location: redirect.href } });
  if (edge.notFoundLog) {
    const referrer = request.headers.get("referer");
    context.get(executionContext).waitUntil(
      context
        .get(clientsContext)()
        .queue(RecordNotFoundAction, {
          host: url.host,
          path: url.pathname,
          ...(referrer ? { referrer } : {}),
        }),
    );
  }
  return response;
};

/**
 * The experience `seo` module's redirect for a path the router does not know, edge-cached for
 * `redirectCacheSeconds` as data. Fails open: a lookup error keeps the 404 page. A target on
 * another site is refused, so a tenant's redirect table can never send visitors off the site.
 */
async function lookupRedirect(
  url: URL,
  edge: EdgeConfig,
  context: Readonly<RouterContextProvider>,
): Promise<{ href: string; status: 301 | 302 } | null> {
  try {
    const cache = caches.default;
    const key = new Request(`${url.origin}/__redirect${url.pathname.toLowerCase()}`);
    let cached = await cache.match(key);
    if (!cached) {
      const answer = await context.get(clientsContext)().query(ResolveRedirectQuery, {
        host: url.host,
        path: url.pathname,
      });
      cached = Response.json(answer, {
        headers: { "Cache-Control": `max-age=${edge.redirectCacheSeconds}` },
      });
      context.get(executionContext).waitUntil(cache.put(key, cached.clone()));
    }
    const redirect = (await cached.json()) as SeoRedirect;
    if (!redirect) return null;
    const target = new URL(redirect.to, url);
    if (target.origin !== url.origin) return null;
    return { href: target.toString(), status: redirect.status };
  } catch (error) {
    context.get(reporterContext).report(error);
    return null;
  }
}

/** Outermost first: the CSP header covers the redirect and the 404 page as well. */
export const middleware = [securityHeaders, notFoundRedirects];
